if (element._productGridInjected) return;
element._productGridInjected = true;

const products = [
  { title: "Best Sunscreen Of 2026: Our Top 10 Picks", img: "https://s.w-x.co/PanamaJackBabySunscreen-HERO-Amazon.png?crop=16:9&width=400&format=pjpg&auto=webp&quality=80", href: "https://weather.com/atmosphere/reviews/best-sunscreen", tag: "Sun Protection", rating: "4.8" },
  { title: "17 Popular Sun Shirts For Men And Women", img: "https://s.w-x.co/WomensSunshirt-HERO-Amazon.png?crop=16:9&width=400&format=pjpg&auto=webp&quality=80", href: "https://weather.com/atmosphere/reviews/long-sleeve-sun-shirts-men-and-women", tag: "Outdoor Apparel", rating: "4.7" },
  { title: "Why You Need A Silk Pillowcase (And Our Top Picks)", img: "https://s.w-x.co/BrooklinenSilkPillow-HERO.png?crop=16:9&width=400&format=pjpg&auto=webp&quality=80", href: "https://weather.com/atmosphere/reviews/best-silk-pillowcases", tag: "Wellness", rating: "4.9" },
  { title: "Fight The Frizz: Best Hair Oils Of 2026", img: "https://s.w-x.co/OuaiHairOil-HERO-Sephora.png?crop=16:9&width=400&format=pjpg&auto=webp&quality=80", href: "https://weather.com/atmosphere/reviews/best-hair-oils-for-every-type-of-hair", tag: "Beauty", rating: "4.6" },
  { title: "12 Travel Essentials To Stash In Your Carry-On", img: "https://s.w-x.co/TravelInspira-luggagescale-HERO.png?crop=16:9&width=400&format=pjpg&auto=webp&quality=80", href: "https://weather.com/atmosphere/reviews/best-travel-products", tag: "Travel Gear", rating: "4.5" },
  { title: "Last Minute Mother's Day Gifts That Can Still Arrive On Time", img: "https://s.w-x.co/FerreroCollection-HERO1-Amazon.png?crop=16:9&width=400&format=pjpg&auto=webp&quality=80", href: "https://weather.com/atmosphere/reviews/last-minute-mothers-day-gift-ideas", tag: "Gifts & Deals", rating: "4.4" }
];

const section = document.createElement('section');
section.setAttribute('aria-label', 'Product Reviews & Deals — Outdoor Gear Picks');
section.className = 'card Card--card--qJMOC Card--cardPadded--d1sUG Card--containerQuery--+S0OY';
section.style.cssText = 'background: linear-gradient(135deg, #f8f9fa 0%, #e9ecef 100%); border-radius: 16px; padding: 28px; margin-top: 24px; box-shadow: 0 4px 20px rgba(0,0,0,0.08);';

const header = document.createElement('div');
header.style.cssText = 'display: flex; justify-content: space-between; align-items: center; margin-bottom: 24px;';

const headingWrap = document.createElement('div');
const h2 = document.createElement('h2');
h2.className = 'Card--cardHeading--M6yBx';
h2.style.cssText = 'font-size: 26px; font-weight: 700; color: #1a1a2e; margin: 0 0 4px 0; letter-spacing: -0.5px;';
h2.textContent = 'Product Reviews & Deals';

const subtitle = document.createElement('p');
subtitle.style.cssText = 'font-size: 14px; color: #6c757d; margin: 0;';
subtitle.textContent = 'Curated picks for outdoor gear, sun protection & travel essentials';

headingWrap.appendChild(h2);
headingWrap.appendChild(subtitle);

const ctaLink = document.createElement('a');
ctaLink.href = 'https://weather.com/atmosphere';
ctaLink.target = '_self';
ctaLink.style.cssText = 'font-size: 14px; color: #0077b6; font-weight: 600; text-decoration: none; display: flex; align-items: center; gap: 4px; white-space: nowrap;';
ctaLink.textContent = 'See more \u2192';

header.appendChild(headingWrap);
header.appendChild(ctaLink);

const grid = document.createElement('div');
grid.style.cssText = 'display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px;';

products.forEach(function(p) {
  const card = document.createElement('a');
  card.href = p.href;
  card.target = '_self';
  card.style.cssText = 'display: block; background: #fff; border-radius: 14px; overflow: hidden; text-decoration: none; color: inherit; transition: transform 0.2s ease, box-shadow 0.2s ease; box-shadow: 0 2px 8px rgba(0,0,0,0.06);';
  card.onmouseover = function() { this.style.transform = 'translateY(-4px)'; this.style.boxShadow = '0 8px 24px rgba(0,0,0,0.12)'; };
  card.onmouseout = function() { this.style.transform = 'translateY(0)'; this.style.boxShadow = '0 2px 8px rgba(0,0,0,0.06)'; };

  const imgWrap = document.createElement('div');
  imgWrap.style.cssText = 'position: relative; padding-top: 65%; overflow: hidden; background: #f1f3f5;';

  const img = document.createElement('img');
  img.src = p.img;
  img.alt = p.title;
  img.style.cssText = 'position: absolute; top: 0; left: 0; width: 100%; height: 100%; object-fit: cover; transition: transform 0.3s ease;';
  card.onmouseover = function() { this.style.transform = 'translateY(-4px)'; this.style.boxShadow = '0 8px 24px rgba(0,0,0,0.12)'; img.style.transform = 'scale(1.05)'; };
  card.onmouseout = function() { this.style.transform = 'translateY(0)'; this.style.boxShadow = '0 2px 8px rgba(0,0,0,0.06)'; img.style.transform = 'scale(1)'; };

  const tag = document.createElement('span');
  tag.textContent = p.tag;
  tag.style.cssText = 'position: absolute; top: 10px; left: 10px; background: rgba(0,119,182,0.9); color: #fff; font-size: 11px; font-weight: 600; padding: 3px 10px; border-radius: 20px; text-transform: uppercase; letter-spacing: 0.5px;';

  imgWrap.appendChild(img);
  imgWrap.appendChild(tag);

  const body = document.createElement('div');
  body.style.cssText = 'padding: 16px;';

  const title = document.createElement('p');
  title.style.cssText = 'font-size: 15px; font-weight: 600; line-height: 1.4; color: #212529; margin: 0 0 8px 0; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;';
  title.textContent = p.title;

  const ratingRow = document.createElement('div');
  ratingRow.style.cssText = 'display: flex; align-items: center; gap: 6px;';

  const stars = document.createElement('span');
  stars.textContent = '\u2605\u2605\u2605\u2605\u2605';
  stars.style.cssText = 'color: #f4a100; font-size: 13px; letter-spacing: 1px;';

  const ratingText = document.createElement('span');
  ratingText.textContent = p.rating;
  ratingText.style.cssText = 'font-size: 12px; color: #6c757d; font-weight: 500;';

  ratingRow.appendChild(stars);
  ratingRow.appendChild(ratingText);

  body.appendChild(title);
  body.appendChild(ratingRow);
  card.appendChild(imgWrap);
  card.appendChild(body);
  grid.appendChild(card);
});

section.appendChild(header);
section.appendChild(grid);
element.parentNode.insertBefore(section, element.nextSibling);
